## Why This Is Asked
Tests the ability to combine fetch, Service Workers, and WebSockets with a practical offline-first UI. Emphasizes conflict resolution via last-writer-wins and a lightweight diff/apply strategy.

## Key Concepts
- Offline-first fetch with Service Worker caching
- WebSocket reconnection strategy with exponential backoff
- Minimal DOM diff/patch engine for efficient row updates
- Offline edit queue with replay on reconnect and per-item last-writer-wins conflict resolution

## Code Example
```javascript
// Fetch wrapper sketch
function createFetchWrapper(baseUrl) {
  return async function fetchWrapper(endpoint, options = {}) {
    const cache = await caches.open('inventory-v1');
    const cached = await cache.match(baseUrl + endpoint);

    if (cached && !options.forceRefresh) {
      return cached;
    }

    const response = await fetch(baseUrl + endpoint, options);
    if (response.ok) {
      cache.put(baseUrl + endpoint, response.clone());
    }
    return response;
  };
}

// WebSocket wrapper sketch
function createWsWrapper(url, handlers) {
  let ws = null;
  let retryDelay = 1000;
  const editQueue = [];

  function connect() {
    ws = new WebSocket(url);

    ws.onopen = () => {
      retryDelay = 1000;
      replayQueue();
      handlers.onOpen?.();
    };

    ws.onmessage = (e) => handlers.onMessage(JSON.parse(e.data));

    ws.onclose = () => {
      setTimeout(connect, retryDelay);
      retryDelay = Math.min(retryDelay * 2, 30000);
    };
  }

  function replayQueue() {
    while (editQueue.length) {
      ws.send(JSON.stringify(editQueue.shift()));
    }
  }

  connect();

  return {
    send: (data) => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify(data));
      } else {
        editQueue.push(data);
      }
    }
  };
}

// Diff applier sketch
function applyDiff(currentItems, updates) {
  const itemMap = new Map(currentItems.map(item => [item.id, item]));

  for (const update of updates) {
    const existing = itemMap.get(update.id);
    if (!existing || update.ts > existing.ts) {
      itemMap.set(update.id, update);
    }
  }

  return Array.from(itemMap.values()).sort((a, b) => b.ts - a.ts);
}
```

## Why This Is Asked
This question tests the ability to design an offline-first, real-time collaboration feature using the Canvas API, WebSocket communication, and Service Workers. It evaluates understanding of robust reconnection strategies, multi-client synchronization, and cross-tab coordination.

## Key Concepts
- Canvas rendering with minimal DOM manipulation; use a single render loop via requestAnimationFrame
- WebSocket-based real-time synchronization with an operation log and CRDT-like merge logic
- Service Worker caching for the app shell and board bitmap to enable offline use
- Cross-tab coordination via BroadcastChannel with resilient reconnect and exponential backoff strategies

## Code Example
```javascript
// WebSocket wrapper (connect, backoff, send, onMessage)
class WS {
  constructor(url) {
    this.url = url;
    this.ws = null;
    this.reconnectDelay = 1000;
    this.maxReconnectDelay = 30000;
    this.handlers = {};
  }

  connect() {
    this.ws = new WebSocket(this.url);
    this.ws.onopen = () => { this.reconnectDelay = 1000; };
    this.ws.onclose = () => this.reconnect();
    this.ws.onmessage = (e) => {
      const msg = JSON.parse(e.data);
      this.handlers[msg.type]?.(msg.payload);
    };
  }

  reconnect() {
    setTimeout(() => {
      this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay);
      this.connect();
    }, this.reconnectDelay);
  }

  send(type, payload) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type, payload }));
    }
  }

  on(type, handler) {
    this.handlers[type] = handler;
  }
}

// opLog for CRDT-like merge
class OpLog {
  constructor() {
    this.ops = [];
    this.vectorClock = {};
  }

  addOp(op) {
    this.ops.push(op);
    this.vectorClock[op.clientId] = (this.vectorClock[op.clientId] || 0) + 1;
  }

  merge(remoteOps) {
    for (const op of remoteOps) {
      const dominated = this.ops.some(local =>
        local.clientId === op.clientId && local.timestamp <= op.timestamp
      );
      if (!dominated) {
        this.ops.push(op);
      }
    }
  }
}

// Service Worker (install/activate/cache)
// sw.js
self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open('whiteboard-v1').then(cache => cache.addAll(['/', '/index.html', '/app.js']))
  );
  self.skipWaiting();
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== 'whiteboard-v1').map(k => caches.delete(k)))
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request).then(cached => cached || fetch(e.request))
  );
});

// Main render wiring
const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const ws = new WS('ws://localhost:8080');
const opLog = new OpLog();

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const op of opLog.ops) {
    ctx.beginPath();
    ctx.moveTo(op.x1, op.y1);
    ctx.lineTo(op.x2, op.y2);
    ctx.stroke();
  }
  requestAnimationFrame(render);
}

canvas.addEventListener('mousemove', (e) => {
  if (e.buttons !== 1) return;
  const op = { x1: lastX, y1: lastY, x2: e.offsetX, y2: e.offsetY };
  opLog.addOp(op);
  ws.send('stroke', op);
  lastX = e.offsetX;
  lastY = e.offsetY;
});

ws.on('stroke', (op) => opLog.addOp(op));
ws.connect();
render();
```

